sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 darkColor;
layout(color) uniform half4 lightColor;
uniform float contrast;
uniform float brightness;
uniform float gamma;
uniform float amount;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float t = saturate((luma(s) - 0.5) * contrast + 0.5 + brightness);
    t = pow(t, 1.0 / max(gamma, 0.01));
    float3 o = mix(s, mix(float3(darkColor.rgb), float3(lightColor.rgb), t), amount);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
